// Arena Engine + Curriculum Data (not 4 separate systems)

class ArenaTrack {
  final String id;
  final String label;
  final String subtitle;
  final String icon;
  final String color;
  const ArenaTrack({required this.id, required this.label, required this.subtitle, required this.icon, required this.color});
}

